-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["7f2827e48b4110a8"] = { "LORD VALTHALAK\n\nNobile draconide ed ex generale dei ⟦Blackrock Spire=Bastioni di Roccianera⟧\n\nPrima del generale Drakkisath c'era sire Valthalak, uno stregone draconide dal potere immenso. Ai Bastioni il comando passa spesso di mano e, sfortunatamente per noi, avremmo avuto una parte nell'ultimo cambio di potere.\n\nUn goblin contrabbandiere e mago di ⟦Booty Bay=Baia del Bottino⟧, ⟦Gremnik Rizzlesprang=Gremnik Brillabotto⟧, ci aveva incaricati di rubare il libro degli incantesimi di Valthalak. Non sappiamo se volesse studiarlo o venderlo (o entrambe le cose), e ormai non ha importanza. Ciò che importa è che ci infiltrammo nella parte alta dei ⟦Blackrock Spire=Bastioni di Roccianera⟧ e uccidemmo sire Valthalak nella sua tana. Fu allora che cominciò il vero divertimento.", "." },
  ["7f315e365737d890"] = { "Eonar benedisse anche la sorella minore di Alexstrasza, l'agile drago verde Ysera, con una parte dell'influsso della natura. Ysera cadde in una trance eterna, legata al Sogno vigile della Creazione. Nota come la Sognatrice, avrebbe vegliato sulle terre selvagge del mondo in crescita dal suo regno verdeggiante, il ⟦Emerald Dream=Sogno di Smeraldo⟧.", "." },
  ["7f5052d154632a4f"] = { "Uccidendo il corpo di Medivh, Lothar e il giovane apprendista bandirono senza volerlo lo spirito di Sargeras nell'abisso. Di conseguenza, anche lo spirito puro e virtuoso di Medivh poté sopravvivere... e vagare nel piano astrale per molti anni a venire.", "." },
  ["7f5c38d5a25591a5"] = { "Come sappiamo che ci amano?\n\nQualcuno potrebbe chiedersi come possano amarci gli Dei Antichi e i loro servitori. Non ci uccidono forse? Non causano dolore e sofferenza a tutti? Come potrebbero esseri tanto votati alla malvagità conoscere l'amore nel loro cuore?\n\nC'è una risposta semplice a questa domanda. Così semplice che non serve nemmeno pronunciarla?", "." },
  ["7fd36af8a82bcbe1"] = { "Un giovane e audace studioso di nome Furion Stormrage, che aveva passato gran parte del suo tempo a studiare gli effetti del Pozzo, cominciò a sospettare che un potere terribile stesse corrompendo gli Alti Nobili e la sua amata regina. Sebbene non potesse immaginare il male che sarebbe venuto, sapeva che la vita degli elfi della notte sarebbe presto cambiata per sempre....", "." },
  ["7ff66bda20b04ddb"] = { "Riteneva che gli antichi elfi e gli anziani uomini che presiedevano il consiglio fossero troppo rigidi nel loro modo di pensare e non abbastanza lungimiranti da porre fine una volta per tutte al conflitto contro il caos. Insofferente alle lunghe discussioni e ai dibattiti, desiderava ardentemente dimostrarsi all'altezza dei suoi pari e dei suoi superiori, e per questo nelle situazioni cruciali sceglieva spesso il valore anziché la saggezza.", "." },
  ["7ffc41ea637c7c2f"] = { "Uno di questi capi, Durotan del Clan Lupi Bianchi, ammonì gli orchi di non perdersi nell'odio e nella furia. Le sue parole caddero però nel vuoto, perché capi più forti, come Grom Hellscream del clan ⟦Warsong=Cantaguerra⟧, si fecero avanti per sostenere la nuova era di guerra e di dominio.", "." },
})
